css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #F5F7F3; }
.dcx a[style*="inline-flex"]{ white-space: nowrap; }
.dcx img{ max-width: 100%; }
@media (prefers-reduced-motion: reduce){.dcx *,.dcx *::before,.dcx *::after{ animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; }
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-h1]{ font-size: 32px !important; }
.dcx [data-h2]{ font-size: 24px !important; }
}
@media (max-width: 1180px){.dcx [data-dlhero]{ background-position: 68% center !important; }
.dcx [data-dispatch]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-track]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-track-phone]{ max-width: 300px; margin: 0 auto; }
.dcx [data-zonegrid]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
}
@media (max-width: 720px){.dcx [data-dlhero]{ background-image: none !important; padding-top: 30px !important; padding-bottom: 30px !important; }
.dcx [data-dlhero-inner]{ max-width: none !important; }
.dcx [data-zonegrid],.dcx [data-dlstats]{ grid-template-columns: minmax(0,1fr) !important; }
}
